import React, { useState, useEffect } from 'react';
import { Box, Typography, Grid, Paper, CircularProgress, Alert } from '@mui/material';
import { PieChart, Pie, BarChart, Bar, XAxis, YAxis, Tooltip, Legend, Cell } from 'recharts';
import { 
  AttachMoney as MoneyIcon,
  ShoppingCart as ExpenseIcon,
  TrendingUp as IncomeIcon,
  Inventory as StockIcon 
} from '@mui/icons-material';
import { getFinancialSummary, getRecentTransactions } from '../services/financeService';
import { getStockSummary } from '../services/stockService';

const Dashboard = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [summary, setSummary] = useState({
    totalIncome: 0,
    totalExpenses: 0,
    netProfit: 0,
    stockValue: 0
  });
  const [transactions, setTransactions] = useState([]);
  const [stockData, setStockData] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const financialData = await getFinancialSummary();
        const recentTransactions = await getRecentTransactions();
        const stockSummary = await getStockSummary();
        
        setSummary({
          totalIncome: financialData?.totalIncome || 0,
          totalExpenses: financialData?.totalExpenses || 0,
          netProfit: financialData?.netProfit || 0,
          stockValue: stockSummary?.totalValue || 0
        });
        
        setTransactions(recentTransactions || []);
        setStockData(stockSummary?.items || []);
        setError(null);
      } catch (err) {
        setError(err.message || 'Failed to load dashboard data');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Data for charts
  const incomeExpenseData = [
    { name: 'Income', value: summary.totalIncome },
    { name: 'Expenses', value: summary.totalExpenses }
  ];

  const recentTransactionsData = transactions.slice(0, 5).map(t => ({
    name: t.category,
    amount: t.amount,
    type: t.type || 'expense'
  }));

  const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042'];

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box my={4}>
        <Alert severity="error">{error}</Alert>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Dashboard Overview
      </Typography>

      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Paper elevation={3} sx={{ p: 3, textAlign: 'center' }}>
            <MoneyIcon color="primary" sx={{ fontSize: 40 }} />
            <Typography variant="h6">Net Profit</Typography>
            <Typography variant="h4" color={summary.netProfit >= 0 ? 'success.main' : 'error.main'}>
              ${summary.netProfit.toFixed(2)}
            </Typography>
          </Paper>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Paper elevation={3} sx={{ p: 3, textAlign: 'center' }}>
            <IncomeIcon color="success" sx={{ fontSize: 40 }} />
            <Typography variant="h6">Total Income</Typography>
            <Typography variant="h4">${summary.totalIncome.toFixed(2)}</Typography>
          </Paper>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Paper elevation={3} sx={{ p: 3, textAlign: 'center' }}>
            <ExpenseIcon color="error" sx={{ fontSize: 40 }} />
            <Typography variant="h6">Total Expenses</Typography>
            <Typography variant="h4">${summary.totalExpenses.toFixed(2)}</Typography>
          </Paper>
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Paper elevation={3} sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>Income vs Expenses</Typography>
            <PieChart width={400} height={300}>
              <Pie
                data={incomeExpenseData}
                cx="50%"
                cy="50%"
                outerRadius={80}
                fill="#8884d8"
                dataKey="value"
                label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
              >
                {incomeExpenseData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default Dashboard;
